const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y₁ = 0.8 sin t（振幅 0.8）' },
      { kind: 'text', payload: 'y₂ = 0.4 sin t（振幅 0.4）' },
      { kind: 'text', payload: '合成 y = y₁ + y₂（合成振幅 1.2）' },
      { kind: 'text', payload: 't' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: '同频同相' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = 80;
    var right = W - 48;
    if (right < left + 60) {
      left = Math.max(36, W * 0.18);
      right = Math.max(left + 60, W - 22);
    }
    var y0 = H * 0.56;
    var scale = Math.min(105, (H - 170) / 2.6);
    if (scale < 12) scale = 12;
    var cycles = 2;
    var N = 360;
    function makeWave(amp) {
      var pts = [];
      for (var i = 0; i <= N; i++) {
        var u = i / N;
        var x = left + (right - left) * u;
        var y = y0 - amp * scale * Math.sin(2 * Math.PI * cycles * u);
        pts.push([x, y]);
      }
      return visualSdk.polyline(pts);
    }
    var wave1 = makeWave(0.8);
    var wave2 = makeWave(0.4);
    var waveSum = makeWave(1.2);
    var xAxis = visualSdk.axis({ x0: left, y0: y0, x1: right, y1: y0, ticks: 6, tickLength: 5 });
    var yAxis = visualSdk.axis({ x0: left, y0: y0 - 1.25 * scale, x1: left, y1: y0 + 1.25 * scale, ticks: 4, tickLength: 5 });
    var swatch1 = visualSdk.polyline([[22, 30], [46, 30]]);
    var swatch2 = visualSdk.polyline([[22, 54], [46, 54]]);
    var swatch3 = visualSdk.polyline([[22, 78], [46, 78]]);
    return {
      schemaVersion: 1,
      sceneId: 'sine-superposition',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'x-axis', commands: xAxis },
        { id: 'y-axis', commands: yAxis },
        { id: 'wave1', commands: wave1 },
        { id: 'wave2', commands: wave2 },
        { id: 'wave-sum', commands: waveSum },
        { id: 'swatch1', commands: swatch1 },
        { id: 'swatch2', commands: swatch2 },
        { id: 'swatch3', commands: swatch3 }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'x-axis', fill: '#4A5568', stroke: { width: 1.4 } },
        { type: 'path', pathId: 'y-axis', fill: '#4A5568', stroke: { width: 1.4 } },
        { type: 'path', pathId: 'wave1', fill: '#1D4ED8', stroke: { width: 2.4 } },
        { type: 'path', pathId: 'wave2', fill: '#15803D', stroke: { width: 2.4 } },
        { type: 'path', pathId: 'wave-sum', fill: '#C2410C', stroke: { width: 3 } },
        { type: 'path', pathId: 'swatch1', fill: '#1D4ED8', stroke: { width: 4 } },
        { type: 'path', pathId: 'swatch2', fill: '#15803D', stroke: { width: 4 } },
        { type: 'path', pathId: 'swatch3', fill: '#C2410C', stroke: { width: 4 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: 52, y: 30 }, hAlign: 'left', vAlign: 'middle', color: '#1D4ED8' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: 52, y: 54 }, hAlign: 'left', vAlign: 'middle', color: '#15803D' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: 52, y: 78 }, hAlign: 'left', vAlign: 'middle', color: '#C2410C' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: right, y: y0 + 10 }, hAlign: 'center', vAlign: 'top', color: '#1F2937' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: left - 10, y: y0 - 1.25 * scale }, hAlign: 'right', vAlign: 'middle', color: '#1F2937' },
        { type: 'label', contentId: metrics[5].contentId, anchor: { x: W - 20, y: 24 }, hAlign: 'right', vAlign: 'top', color: '#4A5568' }
      ] }
    };
  }
};
